function toolDetailPage(slug) {
  const p = state.profile;
  const tool = p.tools.find(t => toolSlug(t.name) === slug);
  if (!tool) { go("tools"); return ""; }

  // Subtyp-spezifische Daten aus Wissensbasis
  const knEntry = subtypeEntry(getProfile());
  const twoPoints = knEntry?.bodySignature?.twoPoints || null;

  const DETAIL_INSTRUCTIONS = {
    "atemimpuls": {
      intro: "Der Atemimpuls ist eine einfache Atemtechnik, die das Nervensystem in Sekunden beruhigt. Längeres Ausatmen aktiviert den Parasympathikus — das Gegenteil von Stress.",
      steps: [
        "Setzen oder stellen Sie sich aufrecht hin.",
        "Atmen Sie durch die Nase ein — zählen Sie dabei langsam bis 4.",
        "Atmen Sie durch den Mund aus — zählen Sie langsam bis 6.",
        "Wiederholen Sie das dreimal.",
        "Bemerken Sie, wie Schultern und Kiefer weicher werden."
      ],
      hinweis: "Ideal in Stresssituationen, vor wichtigen Gesprächen oder als Abendritual."
    },
    "2-punkte-integration": {
      intro: "Die Zwei-Punkte-Integration verbindet Körperbewusstsein mit Gegenwärtigkeit. Sie hilft dabei, Anspannung zu halten ohne zu kämpfen — bis der Körper von selbst mehr Raum findet.",
      steps: [
        "Legen Sie eine Hand auf Punkt 1, die andere auf Punkt 2 (siehe oben).",
        "Halten Sie beide Punkte gleichzeitig im Bewusstsein — wechseln Sie nicht zwischen ihnen.",
        "Atmen Sie ruhig weiter und warten Sie, ohne etwas erzwingen zu wollen.",
        "Nichts verändern. Nichts korrigieren. Nur halten und atmen.",
        "Beobachten Sie, wie sich das Verhältnis der beiden Punkte verändert."
      ],
      hinweis: "Kein Kämpfen — nur Beobachten. Der Körper löst sich, wenn er beides gleichzeitig spüren darf."
    },
    "merksatz": {
      intro: "Der Merksatz ist ein persönlicher Leitsatz, der den Wesenskern Ihres Subtyps in einem Satz zusammenfasst. Regelmäßig wiederholt, wirkt er wie ein innerer Kompass.",
      steps: [
        "Lesen Sie den Merksatz laut vor.",
        "Atmen Sie tief ein und sprechen Sie ihn dann langsam nochmals — als würden Sie ihn fühlen statt nur denken.",
        "Lassen Sie einen Moment stillen Nachklingens entstehen.",
        "Notieren Sie ihn an einem sichtbaren Ort (Spiegel, Notizbuch, Handy-Wallpaper)."
      ],
      hinweis: "Der Merksatz wirkt nicht durch einmaliges Lesen, sondern durch regelmäßige Wiederholung — besonders morgens und abends."
    },
    "koerperuebung": {
      intro: "Körperübungen verankern das Bewusstsein im Körper — weg vom Kopf, weg vom Stress. Was der Körper spürt, kann der Geist loslassen.",
      steps: [
        "Stellen Sie sich aufrecht hin, Füße hüftbreit auseinander.",
        "Spüren Sie das Gewicht Ihrer Füße auf dem Boden — drücken Sie leicht auf.",
        "Bemerken Sie Ihren Rücken: aufrecht aber nicht starr.",
        "Legen Sie eine Hand auf den Bauch, die andere auf die Brust.",
        "Atmen Sie dreimal tief in den Bauch — die Bauchhand hebt sich, die Brusthand bleibt ruhiger.",
        "Beantworten Sie erst danach, was Sie beschäftigt."
      ],
      hinweis: "Diese Übung kann jederzeit und überall gemacht werden — auch im Sitzen."
    },
    "heilmittel-impuls": {
      intro: "Der Heilmittel-Kompass übersetzt Ihr Subtyp-Muster in ein heilkundliches Symbolfeld. Jedes Mittel spricht eine bestimmte Ebene an — körperlich, seelisch und energetisch.",
      steps: [
        'Öffnen Sie den <button class="inline-link" data-route="healing" data-scroll-to="heilmittel-kompass" style="background:none;border:none;padding:0;color:var(--copper);text-decoration:underline;cursor:pointer;font-family:inherit;font-size:inherit;">Heilmittel-Kompass →</button> und betrachten Sie, welches Mittel Ihre Aufmerksamkeit anzieht.',
        "Lesen Sie die zugehörige Bedeutung — lassen Sie sie wirken, ohne sofort zu analysieren.",
        "Wählen Sie heute ein Mittel aus: Homöopathie, Bachblüte, Schüßler-Salz, Edelstein oder Tee.",
        "Verwenden Sie es bewusst — mit dem Gedanken an Ihr Heilungsthema.",
        "Notieren Sie abends, was Sie bemerkt haben."
      ],
      hinweis: "Heilmittel wirken unterstützend, ersetzen aber keine therapeutische Begleitung. Für eine individuelle Beratung steht Detlef Rathmer zur Verfügung."
    },
    "in-stille-sitzen": {
      intro: "Vollkommen still sitzen ist eine der wirkungsvollsten Übungen aus dem Enneagramm-Heilungsmodell. Der Körper zeigt seine eigene Intelligenz — wenn man aufhört, ihn zu steuern.",
      steps: [
        "Setzen Sie sich aufrecht und bequem hin — Rücken gerade, Hände auf den Oberschenkeln.",
        "Schließen Sie die Augen. Lassen Sie alle Kontrolle los.",
        "Tun Sie zwei Minuten lang nichts — keine Korrektur, keine Bewegung.",
        "Beobachten Sie, was der Körper von alleine tut: Atem, Spannung, Impulse.",
        "Öffnen Sie danach die Augen. Bemerken Sie den Unterschied."
      ],
      hinweis: "Wirkung und Ziel: Der Körper zeigt seine eigene Intelligenz. In dieser Zeit (nicht mehr!) kann sich Wesentliches offenbaren."
    },
    "aromatherapie": {
      intro: "Ätherische Öle sprechen das limbische System direkt an — sie wirken schneller als Worte. Das passende Öl für Ihren Subtyp unterstützt die Themen, an denen Sie gerade arbeiten.",
      steps: [
        `Öffnen Sie das Fläschchen Ihres Subtyp-Öls — schauen Sie vorher kurz auf Ihre <button class="inline-link" data-route="oils" data-scroll-to="oil-type-${p.code.replace(/\D/g,'')}" style="background:none;border:none;padding:0;color:var(--copper);text-decoration:underline;cursor:pointer;font-family:inherit;font-size:inherit;">Öl-Karte →</button>.`,
        "Geben Sie einen Tropfen auf Ihre Handflächen und reiben Sie sie sanft aneinander.",
        "Halten Sie die Hände vor Nase und Mund — atmen Sie dreimal tief ein.",
        "Lassen Sie den Duft wirken, ohne ihn zu bewerten.",
        "Sprechen Sie dabei innerlich das Heilungsthema Ihres Subtyps aus."
      ],
      hinweis: "Ätherische Öle immer verdünnt verwenden. Zur vollständigen Öl-Zuordnung aller 27 Subtypen → Öle-Seite in der App."
    },
    "blickqualitaet": {
      intro: "Die Blickqualität ist das sichtbarste Merkmal Ihres Enneagramm-Subtyps. Wer seinen eigenen Blick kennt, erkennt sein Muster — und kann bewusst eine andere Qualität wählen.",
      steps: [
        "Betrachten Sie das Profil-Schaubild oben: Wie ist Ihr typischer Blick beschrieben?",
        "Stellen Sie sich vor einen Spiegel oder schließen Sie die Augen und stellen Sie sich vor, wie Sie gerade schauen.",
        "Bemerken Sie: Ist der Blick eher eng, weit, prüfend, suchend, weich, distanziert?",
        "Wählen Sie bewusst eine andere Blickqualität — einen Moment lang weich, offen, ruhig.",
        "Beobachten Sie, wie sich das auf Ihre innere Haltung auswirkt."
      ],
      hinweis: "Blickqualität ist keine Technik — sie ist ein Spiegel. Wer seinen Blick verändert, verändert seinen inneren Zustand."
    }
  };

  const detail = DETAIL_INSTRUCTIONS[slug] || null;

  // Schaubild-Zuordnung je Werkzeug-Slug
  const TOOL_PAGE_MAP = {
    "2-punkte-integration": "page-2",
    "atemimpuls":           "page-3",
    "koerperuebung":        "page-3",
    "in-stille-sitzen":     "page-3",
    "merksatz":             "page-5",
    "heilmittel-impuls":    "page-4",
    "blickqualitaet":       "page-1",
  };
  const toolPageKey = TOOL_PAGE_MAP[slug] || null;
  const toolPageImg = (toolPageKey && knEntry && knEntry.visualPages)
    ? (knEntry.visualPages.find(pg => pg.src.includes(toolPageKey)) || null)
    : null;
  const seite2Block = toolPageImg ? `
    <figure class="vollseite-karte" style="margin-bottom:1.2rem;">
      <p class="vollseite-karte__hint">Zum Vergrößern antippen</p>
      <div class="card-pg-wrap">
        <img src="${cdnImg(toolPageImg.src)}" alt="${toolPageImg.alt}" class="vollseite-karte__img" loading="lazy"
          onerror="this.closest('.vollseite-karte').style.display='none'" />
        <div class="card-pg-compass" aria-hidden="true">${compassMark("mini")}</div>
      </div>
      <figcaption class="vollseite-karte__titel">${toolPageImg.title || ""}</figcaption>
    </figure>
  ` : "";
  const twoPointsBlock = (slug === "2-punkte-integration" && twoPoints) ? (() => {
    const pts = [twoPoints.point1, twoPoints.point2].filter(Boolean);
    const ptsHtml = pts.map((pt, i) => `
      <div style="display:flex;gap:1rem;align-items:flex-start;padding:.75rem 0;${i > 0 ? "border-top:1px solid rgba(45,74,62,.12);" : ""}">
        <div style="min-width:2rem;height:2rem;border-radius:50%;background:#2d4a3e;color:#fff;display:flex;align-items:center;justify-content:center;font-weight:700;font-size:.85rem;flex-shrink:0;">${i + 1}</div>
        <div>
          <strong style="font-size:1rem;color:#1a2e28;">${pt.name}</strong>
          <span style="font-size:.85rem;color:#4a6e5e;display:block;margin-bottom:.3rem;">${pt.location}</span>
          ${pt.need && pt.need.length ? `<ul style="margin:.2rem 0 0;padding-left:1.1rem;font-size:.88rem;color:#2d4a3e;line-height:1.6;">${pt.need.map(n => `<li>${n}</li>`).join("")}</ul>` : ""}
        </div>
      </div>
    `).join("");
    const microHtml = twoPoints.microInstructions && twoPoints.microInstructions.length
      ? `<div style="margin-top:.75rem;padding-top:.75rem;border-top:1px solid rgba(45,74,62,.15);">
           <p style="font-size:.82rem;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:#2d4a3e;margin:0 0 .4rem;">Mikro-Anleitung</p>
           <ul style="margin:0;padding-left:1.1rem;font-size:.9rem;line-height:1.8;color:#2a3e36;">
             ${twoPoints.microInstructions.map(m => `<li>${m}</li>`).join("")}
           </ul>
         </div>`
      : "";
    return `
      <div style="background:#e8f2ec;border:1.5px solid #2d4a3e;border-radius:14px;padding:1.5rem;margin-bottom:1.2rem;">
        <p style="font-size:.65rem;font-weight:700;letter-spacing:.18em;text-transform:uppercase;color:#2d4a3e;margin:0 0 1rem;">Ihre zwei Punkte · ${p.code}</p>
        ${ptsHtml}
        ${microHtml}
      </div>
    `;
  })() : "";

  const aromatherapieBlock = (slug === "aromatherapie") ? (() => {
    const oel = oelForType(p.code);
    if (!oel) return "";
    return `
      ${oilCard(oel)}
      <p style="text-align:center;margin:.5rem 0 1.2rem;">
        <button class="ghost-link" data-route="oils" style="font-size:.88rem;">Alle 9 Öl-Karten ansehen →</button>
      </p>
    `;
  })() : "";

  return shell(`
    <section class="narrow" style="padding:1.5rem 1rem 0;">
      <button class="ghost-link" data-route="tools">← Zurück zu Werkzeuge</button>
    </section>
    <section class="narrow centered" style="padding:1rem 1rem 0;">
      <p class="eyebrow">${tool.label}</p>
      <h1 style="font-size:1.8rem;">${tool.name}</h1>
      <p style="font-style:italic;color:var(--text-muted,#888);font-size:.95rem;">${p.code} · Ihr Werkzeug für heute</p>
    </section>

    <section class="narrow" style="padding:1rem 1rem 2rem;">
      ${aromatherapieBlock}
      ${seite2Block}
      ${twoPointsBlock}

      <div style="background:var(--cream,#f9f6f0);border-radius:14px;padding:1.5rem;margin-bottom:1.2rem;">
        <p style="font-size:1.05rem;line-height:1.7;margin:0;">${tool.text}</p>
      </div>

      ${detail ? `
        <div style="background:#fff;border:1px solid rgba(0,0,0,.07);border-radius:14px;padding:1.5rem;margin-bottom:1.2rem;">
          <p style="font-size:.95rem;line-height:1.7;margin:0 0 1.2rem;color:#444;">${detail.intro}</p>
          <h3 style="font-size:1rem;margin:0 0 .75rem;">So geht es:</h3>
          <ol style="padding-left:1.2rem;margin:0 0 1.2rem;line-height:1.8;font-size:.95rem;">
            ${detail.steps.map(s => `<li style="margin-bottom:.4rem;">${s}</li>`).join("")}
          </ol>
          <p style="font-size:.88rem;color:#888;font-style:italic;margin:0;border-top:1px solid #eee;padding-top:.8rem;">💡 ${detail.hinweis}</p>
        </div>
      ` : ""}

      ${["atemimpuls","koerperuebung","in-stille-sitzen"].includes(slug) ? bookTip("7-wege-zu-dir-selbst-lebenskunst-fuer-den-alltag", "Atemübungen, Stille, Körperbewusstsein – sieben einfache und wirkungsvolle Wege zu sich selbst.", "7 Wege zu Dir selbst") : ""}

      <div style="display:flex;flex-direction:column;gap:.75rem;">
        <button class="secondary" data-route="tools">Zurück zu allen Werkzeugen</button>
        <button class="secondary" data-route="tcm">TCM-Profil &amp; Akupunktur ansehen</button>
        <button class="secondary" data-route="subtype/${getProfile()}">Mein Subtyp-Kompass</button>
      </div>
    </section>
  `);
}

// Buchtipp-Banner: bookTip(buchId, teaser)
// buchId = Schlüssel aus buecher-daten.js, teaser = kurze Einladung
const VERLAG_BASE = "https://www.verlagshausrathmer.com/buch.html?slug=";
function bookTip(buchId, teaser, title) {
  return `
    <a class="book-tip" href="${VERLAG_BASE}${buchId}" target="_blank" rel="noopener">
      <span class="book-tip__icon">📖</span>
      <div class="book-tip__text">
        <strong>Buchtipp: »${title}«</strong>
        <span>${teaser}</span>
      </div>
      <span class="book-tip__arrow">→</span>
    </a>
  `;
}

function relatedLinks(links) {
  if (!links || !links.length) return "";
  const ALBUM_KEYS = ["jazz", "musik", "stille", "songs", "lieder", "alben", "homoeopathie-songs"];
  const PORTRAIT_PREFIXES = ["beruehmte-", "kriminalpsychologie-", "astrologie-"];
  const isAlbum    = r => ALBUM_KEYS.some(k => r.includes(k));
  const isPortrait = r => PORTRAIT_PREFIXES.some(p => r.startsWith(p) && r.length > p.length);
  const hasAlbum    = links.some(l => isAlbum(l.route));
  const hasPortrait = links.some(l => isPortrait(l.route));
  const hasOverview = links.some(l => !isAlbum(l.route) && !isPortrait(l.route));
  const heading = hasAlbum && hasOverview       ? "\xc4hnliche \xdcbersichten und Alben"
                : hasAlbum                      ? "\xc4hnliche Alben"
                : hasPortrait && hasOverview    ? "\xc4hnliche Portr\xe4ts und \xdcbersichten"
                : hasPortrait                   ? "\xc4hnliche Portr\xe4ts"
                :                                "\xc4hnliche \xdcbersichten";
  const buttons = links.map(({route, label}) =>
    `<button class="related-link-btn" data-route="${route}" style="background:none;border:1px solid var(--gold);color:var(--copper);border-radius:20px;padding:.35rem .95rem;font-size:0.82rem;font-family:'EB Garamond',serif;cursor:pointer;white-space:nowrap;">${label} &#8594;</button>`
  ).join("");
  return `
    <div style="margin-top:2rem;padding-top:1.25rem;border-top:1px solid var(--border);">
      <p style="font-size:0.75rem;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);margin:0 0 .6rem;">&#10022;&nbsp;${heading}</p>
      <div style="display:flex;flex-wrap:wrap;gap:.5rem;">${buttons}</div>
    </div>
  `;
}

function healingPage() {
  const code = getProfile();
  // Replace #healing in browser history with #subtype/code so back-button works correctly
  history.replaceState(null, "", "#subtype/" + code);
  state.route = "subtype/" + code;
  window._currentRoute = state.route;
  return subtypePage(code);
}

